import inspect
import math


_START = [0.4564, 0.0656, 0.1672]
_X_BOUNDS = (0.40, 0.50)
_Y_BOUNDS = (-0.05, 0.05)
_CLEARANCE = 0.003
_STEP = 0.00025
_TOUCH_FORCE = 6.0
_INSERT_FORCE = 12.0


def _force_vector(value, allow_sequence=True):
    if isinstance(value, dict):
        for key in ("wrench", "force", "forces", "tcp_force", "contact_force"):
            if key in value:
                result = _force_vector(value[key])
                if result is not None:
                    return result
        if all(k in value for k in ("fx", "fy", "fz")):
            return tuple(float(value[k]) for k in ("fx", "fy", "fz"))
        if all(k in value for k in ("x", "y", "z")) and allow_sequence:
            return tuple(float(value[k]) for k in ("x", "y", "z"))
        return None

    if allow_sequence:
        if isinstance(value, (int, float)):
            return (0.0, 0.0, float(value))
        try:
            if len(value) >= 3:
                return tuple(float(value[i]) for i in range(3))
        except (TypeError, ValueError, IndexError):
            pass
    return None


def _rotation_vector(yaw_degrees):
    # Rz(yaw) Rx(pi): tool z points down.
    half = math.radians(yaw_degrees) / 2.0
    return [math.pi * math.cos(half), math.pi * math.sin(half), 0.0]


