        self.motion, self.absolute_yaw = self._find_motion()

    def _find_force_reader(self):
        for name in (
            "get_wrench", "wrench", "get_tcp_force", "get_force",
            "get_forces", "force", "forces", "contact_force",
            "get_contact_force", "get_force_torque", "force_torque",
            "read_force", "sense",
        ):
            function = getattr(self.api, name, None)
            if not callable(function):
                continue
            try:
                signature = inspect.signature(function)
                signature.bind()
            except TypeError:
                continue
            except ValueError:
                pass
            try:
                result = _force_vector(function())
            except (TypeError, NotImplementedError, AttributeError):
                continue
            if result is not None:
                return function
        return None

    def _find_motion(self):
        """Select a command by its signature, without trial motion calls."""
        for name in (
            "move_relative", "move_delta", "move_by",
            "move_tcp", "move", "move_to", "set_tcp_pose", "movel",
        ):
            function = getattr(self.api, name, None)
            if not callable(function):
                continue
