            names = set(params)
            doc = (getattr(function, "__doc__", "") or "").lower()
            radians = "radian" in doc and "degree" not in doc

            relative_xyz = {"dx", "dy", "dz"} <= names
            absolute_xyz = {"x", "y", "z"} <= names
            vector_name = next(
                (n for n in ("delta", "dpos", "translation", "position",
                             "target_position", "pose", "target_pose", "action")
