import math
import re


START_TCP = (0.4564, 0.0656, 0.1672)
SAFE_Z = 0.1772
LOWEST_TCP_Z = 0.015
FORCE_CHANGE_LIMIT_N = 5.0
XY_STEP = 0.005
Z_STEP = 0.001
GRID_SPACING = 0.0005


def _normal(name):
    return re.sub(r"[^a-z0-9]", "", name.lower())


def _number(value):
    return isinstance(value, (int, float)) and not isinstance(value, bool)


def _sequence(value):
    if isinstance(value, (list, tuple)):
        return value
    if hasattr(value, "tolist"):
        return value.tolist()
    return None


def _signature(fn):
    try:
        return inspect.signature(fn)
    except (TypeError, ValueError):
        return None


def _no_required_arguments(fn):
    sig = _signature(fn)
    return sig is not None and all(
        p.default is not inspect.Parameter.empty
        or p.kind in (p.VAR_POSITIONAL, p.VAR_KEYWORD)
        for p in sig.parameters.values()
    )


def _getter(api, names):
    for name in names:
        fn = getattr(api, name, None)
        if callable(fn) and _no_required_arguments(fn):
            return fn
    return None


def _radians(fn):
    text = (getattr(fn, "__doc__", "") or "").lower()
    return bool(re.search(r"\bradians?\b|\brad\b", text)) and not bool(
        re.search(r"\bdegrees?\b|\bdeg\b", text)
    )


def _pose(value, radians=False):
    """Return (position, optional yaw in degrees), or None."""
    if isinstance(value, dict):
        yaw = value.get("yaw", value.get("theta"))
        for key in ("tcp_pose", "tcp", "ee_pose", "pose", "position", "xyz"):
            if key in value:
                answer = _pose(value[key], radians)
                if answer is not None:
                    xyz, nested_yaw = answer
                    if _number(yaw):
                        nested_yaw = math.degrees(yaw) if radians else float(yaw)
                    return xyz, nested_yaw
        if all(_number(value.get(k)) for k in ("x", "y", "z")):
            angle = None
            if _number(yaw):
                angle = math.degrees(yaw) if radians else float(yaw)
            return [float(value[k]) for k in ("x", "y", "z")], angle
        return None

    seq = _sequence(value)
    if seq is None:
        return None
    if len(seq) == 2:
        xyz = _sequence(seq[0])
        if xyz is not None and len(xyz) == 3 and all(map(_number, xyz)):
            yaw = seq[1]
            angle = None
            if _number(yaw):
                angle = math.degrees(yaw) if radians else float(yaw)
            return list(map(float, xyz)), angle
    if len(seq) in (3, 4, 6) and all(map(_number, seq)):
        yaw = seq[3] if len(seq) == 4 else seq[5] if len(seq) == 6 else None
        if yaw is not None and radians:
            yaw = math.degrees(yaw)
        return list(map(float, seq[:3])), yaw
    return None


def _contact(value):
    if isinstance(value, bool):
        return value
    if isinstance(value, dict):
        for key in ("contact", "in_contact", "collision", "blocked"):
            if value.get(key) is True:
                return True
        for key in ("state", "observation", "info"):
            if isinstance(value.get(key), dict) and _contact(value[key]):
                return True
    return False


def _force(value):
    if isinstance(value, dict):
        for key in ("force", "forces", "wrench", "tcp_force", "ft"):
            if key in value:
                answer = _force(value[key])
                if answer is not None:
                    return answer
        if all(_number(value.get(k)) for k in ("fx", "fy", "fz")):
            return tuple(float(value[k]) for k in ("fx", "fy", "fz"))
        if all(_number(value.get(k)) for k in ("x", "y", "z")):
            return tuple(float(value[k]) for k in ("x", "y", "z"))
    seq = _sequence(value)
    if seq is not None and len(seq) >= 3 and all(map(_number, seq[:3])):
        return tuple(map(float, seq[:3]))
    if _number(value):
        return (0.0, 0.0, float(value))
    return None


class _Motion:
    """Bind explicit translation-and-yaw arguments, including vector deltas."""

    def __init__(self, api):
        preferred = (
            "move_relative", "move_rel", "move_delta", "move_cartesian",
            "move_tcp", "move_ee", "move_to", "move", "step",
        )
        names = list(preferred)
        names.extend(
            name for name in dir(api)
            if not name.startswith("_")
            and name not in names
            and name.startswith(("move", "servo", "translate"))
        )
        diagnostics = []
        for name in names:
            fn = getattr(api, name, None)
            if not callable(fn):
                continue
            sig = _signature(fn)
            diagnostics.append("{}{}".format(name, sig or "(opaque)"))
            if sig is None:
                continue
            bound = self._bind(name, fn, sig)
            if bound is not None:
                self.fn, self.sig, self.fields, self.relative, self.rad = bound
                return
        raise RuntimeError(
            "Cannot safely bind the exposed motion interface. Supply its "
            "signature/schema rather than probing unknown robot actions. Found: "
            + ", ".join(diagnostics)
        )

    @staticmethod
    def _bind(name, fn, sig):
        params = list(sig.parameters.values())
        fields = {}
        xyz_mode = None

        relative_axes = {
            "dx": 0, "deltax": 0, "dy": 1, "deltay": 1,
            "dz": 2, "deltaz": 2,
        }
        absolute_axes = {
            "x": 0, "targetx": 0, "y": 1, "targety": 1,
            "z": 2, "targetz": 2,
        }
        relative_vectors = {
            "dpos", "dxyz", "deltapos", "deltaposition",
            "deltatranslation", "translationdelta",
        }
        absolute_vectors = {"position", "targetposition", "targetxyz", "xyz"}
        relative_yaws = {"dyaw", "deltayaw", "yawdelta", "dtheta", "deltatheta"}
        absolute_yaws = {"yaw", "targetyaw", "theta"}
        axes = set()
        vector = False
        yaw_mode = None

        for p in params:
            n = _normal(p.name)
            if n in relative_axes:
                mode, field = True, ("axis", relative_axes[n])
                axes.add(relative_axes[n])
            elif n in absolute_axes:
                mode, field = False, ("axis", absolute_axes[n])
                axes.add(absolute_axes[n])
            elif n in relative_vectors:
                mode, field, vector = True, ("vector", None), True
            elif n in absolute_vectors:
                mode, field, vector = False, ("vector", None), True
            elif n in relative_yaws:
                fields[p.name] = ("yaw", None)
                yaw_mode = True
                continue
            elif n in absolute_yaws:
                fields[p.name] = ("yaw", None)
                yaw_mode = False
                continue
            elif p.kind in (p.VAR_POSITIONAL, p.VAR_KEYWORD):
                continue
            elif p.default is not inspect.Parameter.empty:
                continue
            else:
                return None

            if xyz_mode is not None and xyz_mode != mode:
                return None
            xyz_mode = mode
            fields[p.name] = field

        if xyz_mode is None or yaw_mode is None:
            return None
        if not vector and axes != {0, 1, 2}:
            return None

        # Mixed absolute/relative interfaces require an explicit contract.
        if xyz_mode != yaw_mode:
            return None

        rad = _radians(fn)
        if any("rad" in p.name.lower() for p in params):
            rad = True
        return fn, sig, fields, xyz_mode, rad

    def call(self, target, yaw, current, current_yaw):
        xyz = (
            [target[i] - current[i] for i in range(3)]
            if self.relative else list(target)
        )
        angle = yaw - current_yaw if self.relative else yaw
        if self.rad:
            angle = math.radians(angle)

        args, kwargs = [], {}
        for p in self.sig.parameters.values():
            if p.kind in (p.VAR_POSITIONAL, p.VAR_KEYWORD):
                continue
            if p.name in self.fields:
                kind, index = self.fields[p.name]
                value = xyz[index] if kind == "axis" else xyz if kind == "vector" else angle
            elif p.kind == p.POSITIONAL_ONLY:
                value = p.default
            else:
                continue
            if p.kind == p.POSITIONAL_ONLY:
                args.append(value)
            else:
                kwargs[p.name] = value
        return self.fn(*args, **kwargs)


class _Controller:
    def __init__(self, api):
        self.api = api
        self.motion = _Motion(api)
        self.read_pose = _getter(api, (
            "tcp_pose", "get_tcp_pose", "get_ee_pose", "ee_pose",
            "peg_pose", "get_pose", "pose", "get_state", "observe",
        ))
        self.read_contact = _getter(api, (
            "in_contact", "is_contact", "get_contact", "contact",
        ))
        self.read_force = _getter(api, (
            "get_tcp_force", "tcp_force", "get_wrench", "wrench",
            "get_force", "force", "forces", "ft",
        ))
        self.xyz = list(START_TCP)
        self.yaw = 0.0
        self.world_yaw_known = not self.motion.relative
        self.have_pose_feedback = False
        self.state = None
        if self.read_pose:
            self.state = self.read_pose()
            self._update_pose(self.state, _radians(self.read_pose))
        self.force_baseline = (
            _force(self.read_force()) if self.read_force else None
        )
        self.have_guard = (
            self.have_pose_feedback
            or self.read_contact is not None
            or self.force_baseline is not None
        )

    def _update_pose(self, state, radians):
        answer = _pose(state, radians)
        if answer is None and isinstance(state, dict):
            for key in ("state", "observation"):
                answer = _pose(state.get(key), radians)
                if answer is not None:
                    break
        if answer is not None:
            self.xyz, yaw = answer
            self.have_pose_feedback = True
            if yaw is not None:
                self.yaw = float(yaw)
                self.world_yaw_known = True
            return True
        return False

    def move(self, target, yaw=None):
        yaw = self.yaw if yaw is None else yaw
        old = list(self.xyz)
        descending = target[2] < old[2] - 1e-8
        result = self.motion.call(target, yaw, old, self.yaw)

        # Dead reckoning is only a fallback; actual pose feedback takes priority.
        self.xyz, self.yaw = list(target), yaw
        observed = self._update_pose(result, self.motion.rad)
        self.state = result
        if self.read_pose:
            self.state = self.read_pose()
            observed = self._update_pose(
                self.state, _radians(self.read_pose)
            ) or observed

        hit = _contact(result) or _contact(self.state)
        if self.read_contact:
            hit = hit or _contact(self.read_contact())
        if self.read_force:
            force = _force(self.read_force())
            if force is not None and self.force_baseline is not None:
                delta = math.sqrt(sum(
                    (a - b) ** 2 for a, b in zip(force, self.force_baseline)
                ))
                hit = hit or delta >= FORCE_CHANGE_LIMIT_N
        if descending and observed:
            hit = hit or self.xyz[2] > target[2] + 0.00025

        if isinstance(result, dict):
            self.have_guard = self.have_guard or any(
                key in result for key in ("contact", "in_contact", "collision", "blocked")
            )
        self.have_guard = self.have_guard or self.have_pose_feedback
        return hit

    def retract(self):
        # Retraction is vertical; do not drag an engaged square peg sideways.
        while self.xyz[2] < SAFE_Z - 1e-6:
            before = self.xyz[2]
            self.move([self.xyz[0], self.xyz[1], min(SAFE_Z, before + Z_STEP)])
            if self.xyz[2] < before + 0.00005:
                raise RuntimeError("Vertical retraction is blocked; operator intervention required.")

    def traverse(self, x, y):
        self.retract()
        while math.hypot(x - self.xyz[0], y - self.xyz[1]) > 1e-6:
            dx, dy = x - self.xyz[0], y - self.xyz[1]
            length = math.hypot(dx, dy)
            scale = min(1.0, XY_STEP / length)
            before = self.xyz[:2]
            hit = self.move([
                self.xyz[0] + scale * dx,
                self.xyz[1] + scale * dy,
                SAFE_Z,
            ])
            if hit:
                raise RuntimeError("Unexpected contact during above-block traversal.")
            if math.hypot(self.xyz[0] - before[0], self.xyz[1] - before[1]) < 1e-7:
                raise RuntimeError("Cartesian traversal made no progress.")

    def orient(self, yaw):
        self.retract()
        while abs(yaw - self.yaw) > 1e-6:
            delta = max(-2.0, min(2.0, yaw - self.yaw))
            if self.move(self.xyz[:], self.yaw + delta):
                raise RuntimeError("Unexpected contact while rotating above the block.")

    def attempt(self):
        if not self.have_guard:
            raise RuntimeError(
                "Insertion requires contact/force feedback or observed Cartesian "
                "stall feedback from the simulator."
            )
        while self.xyz[2] > LOWEST_TCP_Z + 1e-6:
            target = self.xyz[:]
            target[2] = max(LOWEST_TCP_Z, target[2] - Z_STEP)
            hit = self.move(target)
            if self.api.done():
                return True
            if hit:
                break
        self.retract()
        return False


def _spiral(radius):
    """Every integer grid point in the square, starting at its centre."""
    yield 0, 0
    for r in range(1, radius + 1):
        for x in range(-r + 1, r + 1):
            yield x, -r
        for y in range(-r + 1, r + 1):
            yield r, y
        for x in range(r - 1, -r - 1, -1):
            yield x, r
        for y in range(r - 1, -r - 1, -1):
            yield -r, y


def run(api):
    if api.done():
        return True

    robot = _Controller(api)

    # A small upward motion is safe from the recorded, unchanged state. It also
    # allows motion-returned pose/contact feedback to establish the guard.
    robot.retract()
    if not robot.have_guard:
        raise RuntimeError(
            "No usable insertion feedback is exposed. The simulator has not "
            "been reset and no downward search motion has been commanded."
        )

    if robot.world_yaw_known:
        # Two-degree spacing gives at most one degree of yaw mismatch.
        angles = [0.0]
        for angle in range(2, 15, 2):
            angles.extend((float(angle), -float(angle)))
        angles.extend((15.0, -15.0))
    else:
        # Unknown initial yaw: cover the square peg's complete 90-degree
        # symmetry interval, rather than assume that its initial yaw is zero.
        origin = robot.yaw
        angles = [origin + float(i) for i in range(90)]

    # A 0.5 mm grid plus the yaw spacing above fits the 0.5 mm per-side
    # clearance in the ideal stated geometry. This exhaustive fallback can be
    # expensive; a calibrated hole sensor would be preferable in production.
    radius = int(round(0.05 / GRID_SPACING))
    for angle in angles:
        robot.orient(angle)
        for ix, iy in _spiral(radius):
            x = 0.45 + ix * GRID_SPACING
            y = iy * GRID_SPACING
            robot.traverse(x, y)
            if robot.attempt():
                return True

    robot.retract()
    raise RuntimeError(
        "Guarded workspace/yaw search exhausted without api.done(). "
        "Check calibration, motion units, TCP convention, and contact feedback."
    )
